using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
internal class CommandScript:IRunCommand{
 struct E:IEquatable<E>{public int a,b;public E(int x,int y){a=Math.Min(x,y);b=Math.Max(x,y);}public bool Equals(E o)=>a==o.a&&b==o.b;public override bool Equals(object o)=>o is E&&Equals((E)o);public override int GetHashCode()=>a*397^b;}
 public void Execute(ExecutionResult result){var scenes=AssetDatabase.FindAssets("t:Scene",new[]{"Assets/Scenes"}).Select(AssetDatabase.GUIDToAssetPath).Where(p=>!p.Contains("RestoreBackups")&&!Path.GetFileName(p).StartsWith("_Recovery_")&&!p.Contains("Enroth_Linked")).OrderBy(p=>p).ToArray();var rows=new List<string>{"scene|mesh|verts|tris|boundary_edges|avg_boundary_seg|max_boundary_seg"};
 foreach(var sp in scenes){var s=EditorSceneManager.OpenScene(sp,OpenSceneMode.Single);var r=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).FirstOrDefault(x=>x.name.StartsWith("Water -"));if(!r)continue;var mf=r.GetComponent<MeshFilter>();if(!mf||!mf.sharedMesh)continue;var m=mf.sharedMesh;var count=new Dictionary<E,int>();long tris=0;for(int sm=0;sm<m.subMeshCount;sm++){var ix=m.GetIndices(sm);for(int i=0;i+2<ix.Length;i+=3){tris++;var es=new[]{new E(ix[i],ix[i+1]),new E(ix[i+1],ix[i+2]),new E(ix[i+2],ix[i])};foreach(var e in es)count[e]=count.TryGetValue(e,out var c)?c+1:1;}}var b=count.Where(k=>k.Value==1).Select(k=>k.Key).ToArray();double sum=0,max=0;var v=m.vertices;foreach(var e in b){double d=Vector3.Distance(v[e.a],v[e.b]);sum+=d;if(d>max)max=d;}rows.Add(Path.GetFileNameWithoutExtension(sp)+"|"+AssetDatabase.GetAssetPath(m)+"|"+m.vertexCount+"|"+tris+"|"+b.Length+"|"+(b.Length>0?sum/b.Length:0)+"|"+max);}
 Directory.CreateDirectory("Validation/FinalWorld");File.WriteAllLines("Validation/FinalWorld/water_mesh_stats.txt",rows);EditorSceneManager.OpenScene("Assets/Scenes/Enroth_Linked_OpenWorld.unity",OpenSceneMode.Single);result.Log("water stats scenes="+(rows.Count-1));}
}